104:-- day_ninety_question: the six Day-90 leadership test questions, verbatim (B0136-B0141). evidence_record_types names the
106:CREATE TABLE day_ninety_question (
108:  ordinal               smallint NOT NULL CONSTRAINT day_ninety_question_ordinal_key UNIQUE CHECK (ordinal BETWEEN 1 AND 6),
111:  source_ref            text NOT NULL CONSTRAINT day_ninety_question_source_ref_key UNIQUE CHECK (source_ref ~ '^B01(3[6-9]|4[01])$'),
114:GRANT SELECT ON day_ninety_question TO mth_app;
115:INSERT INTO day_ninety_question (code, ordinal, text_en, text_ar, source_ref, evidence_record_types) VALUES
179:  task_kind          text NOT NULL CHECK (task_kind IN ('action', 'output', 'day_ninety_test', 'custom')),
331:-- day_ninety_test: the Day-90 leadership test of a plan (REQ-PB-087), created with the plan and scheduled on day 90
334:CREATE TABLE day_ninety_test (
338:  plan_id           uuid NOT NULL CONSTRAINT day_ninety_test_plan_key UNIQUE,
349:  CONSTRAINT day_ninety_test_transformation_id_id_key UNIQUE (transformation_id, id),
350:  CONSTRAINT day_ninety_test_plan_fkey FOREIGN KEY (transformation_id, plan_id)
352:  CONSTRAINT day_ninety_test_completed_complete CHECK ((status = 'completed') = (completed_at IS NOT NULL)
355:CREATE FUNCTION day_ninety_test_guard() RETURNS trigger
359:    RAISE EXCEPTION 'day_ninety_test: a test is created open with no response'
360:      USING ERRCODE = 'check_violation', CONSTRAINT = 'day_ninety_test_created_open';
364:      RAISE EXCEPTION 'day_ninety_test: the plan never changes, and a completed test is final'
365:        USING ERRCODE = 'check_violation', CONSTRAINT = 'day_ninety_test_completed_final';
370:CREATE TRIGGER day_ninety_test_guard BEFORE INSERT OR UPDATE ON day_ninety_test FOR EACH ROW EXECUTE FUNCTION day_ninety_test_guard();
371:SELECT p2_attach_guards('day_ninety_test', true);
372:GRANT SELECT, INSERT, UPDATE ON day_ninety_test TO mth_app;
374:-- day_ninety_response: one leader response per question (yes or no, with an optional comment and evidence), written only
376:CREATE TABLE day_ninety_response (
381:  question_code     text NOT NULL REFERENCES day_ninety_question (code) ON DELETE RESTRICT ON UPDATE RESTRICT,
391:  CONSTRAINT day_ninety_response_test_fkey FOREIGN KEY (transformation_id, test_id)
392:    REFERENCES day_ninety_test (transformation_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
393:  CONSTRAINT day_ninety_response_evidence_fkey FOREIGN KEY (transformation_id, evidence_id)
395:  CONSTRAINT day_ninety_response_key UNIQUE (test_id, question_code)
397:CREATE FUNCTION day_ninety_response_guard() RETURNS trigger
401:    RAISE EXCEPTION 'day_ninety_response: the test and question never change'
402:      USING ERRCODE = 'check_violation', CONSTRAINT = 'day_ninety_response_identity_fixed';
404:  IF EXISTS (SELECT 1 FROM day_ninety_test t WHERE t.id = NEW.test_id AND t.status <> 'open') THEN
405:    RAISE EXCEPTION 'day_ninety_response: responses are recorded only while the test is open'
406:      USING ERRCODE = 'check_violation', CONSTRAINT = 'day_ninety_response_test_open';
410:CREATE TRIGGER day_ninety_response_guard BEFORE INSERT OR UPDATE ON day_ninety_response FOR EACH ROW EXECUTE FUNCTION day_ninety_response_guard();
411:SELECT p2_attach_guards('day_ninety_response', true);
412:GRANT SELECT, INSERT, UPDATE ON day_ninety_response TO mth_app;
415:CREATE FUNCTION day_ninety_test_counted() RETURNS trigger
418:  tid uuid := CASE WHEN TG_TABLE_NAME = 'day_ninety_test' THEN (to_jsonb(NEW)->>'id')::uuid ELSE (to_jsonb(NEW)->>'test_id')::uuid END;
420:  IF (SELECT answered_count FROM day_ninety_test WHERE id = tid) <> (SELECT count(*) FROM day_ninety_response r WHERE r.test_id = tid) THEN
421:    RAISE EXCEPTION 'day_ninety_test %: answered_count must equal its responses', tid
422:      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = 'day_ninety_test_answered_count';
426:CREATE CONSTRAINT TRIGGER day_ninety_test_counted AFTER INSERT OR UPDATE ON day_ninety_test
427:  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION day_ninety_test_counted();
428:CREATE CONSTRAINT TRIGGER day_ninety_response_counted AFTER INSERT ON day_ninety_response
429:  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION day_ninety_test_counted();
