    case "day_ninety_response_key":
      return problems.versionConflict(null);
    case "day_ninety_test_created_open":
    case "day_ninety_response_identity_fixed":
    case "day_ninety_test_answered_count":
      return problems.internal();
    default:
      return null;
  }
}

